async function generateCode(prompt, model, tokenizer, maxLength = 100, numReturnSequences = 1) {
  const inputIds = tokenizer.encode(prompt, { return_tensors: 'pt' });
  const output = await model.generate(inputIds, {
    max_length: maxLength,
    num_return_sequences: numReturnSequences,
    no_repeat_ngram_size: 2,
    temperature: 0.7,
    top_k: 50,
    top_p: 0.95,
    pad_token_id: tokenizer.eos_token_id,
  });
  return output.map((outputSeq) => tokenizer.decode(outputSeq, { skip_special_tokens: true }));
}

