```
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onChange }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestionsList, setSuggestionsList] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const handleInputValueChange = (event) => {
      const value = event.target.value;
      setInputValue(value);
      const lowerCaseValue = value.toLowerCase();
      const filteredSuggestions = suggestions.filter((suggestion) => {
        return suggestion.toLowerCase().includes(lowerCaseValue);
      });
      setSuggestionsList(filteredSuggestions);
    };

    const handleSuggestionsListClick = (event) => {
      const suggestion = event.target.textContent;
      onChange(suggestion);
      setInputValue(suggestion);
    };

    const handleKeyDown = (event) => {
      switch (event.key) {
        case 'ArrowDown':
          setActiveSuggestionIndex((activeSuggestionIndex + 1) % suggestionsList.length);
          break;
        case 'ArrowUp':
          setActiveSuggestionIndex((activeSuggestionIndex - 1 + suggestionsList.length) % suggestionsList.length);
          break;
        case 'Enter':
          if (activeSuggestionIndex !== -1) {
            onChange(suggestionsList[activeSuggestionIndex]);
            setInputValue(suggestionsList[activeSuggestionIndex]);
            setActiveSuggestionIndex(-1);
          }
          break;
        default:
          break;
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [suggestions, onChange]);

  const renderSuggestions = () => {
    if (suggestionsList.length === 0) {
      return null;
    }

    return (
      <ul>
        {suggestionsList.map((suggestion, index) => (
          <li
            key={index}
            style={{
              backgroundColor: activeSuggestionIndex === index ? '#eee' : 'transparent',
            }}
            onClick={handleSuggestionsListClick}
          >
            {suggestion}
          </li>
        ))}
      </ul>
    );
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputValueChange}
        placeholder="Type to autocomplete"
      />
      {renderSuggestions()}
    </div>
  );
};

export default Autocomplete;
```
This component takes in two props: `suggestions` and `onChange`. `suggestions` is an array of strings that represent the possible autocomplete suggestions. `onChange` is a function that will be called with the selected suggestion as an argument.

The component uses three state variables: `inputValue` to store the current input value, `suggestionsList` to store the filtered list of suggestions, and `activeSuggestionIndex` to keep track of the currently active suggestion.

