```csharp
using System;
using System.Net;
using System.IO;

class HttpServer
{
    static void Main(string[] args)
    {
        // Créer un nouvel objet HttpListener
        HttpListener listener = new HttpListener();

        // Configurer l'écouteur pour répondre aux requêtes HTTP sur le port 8080
        listener.Prefixes.Add("http://localhost:8080/");

        // Lancer l'écouteur
        listener.Start();

        Console.WriteLine("Server started. Listening for requests...");

        while (true)
        {
            // Attendre la prochaine requête
            HttpListenerContext context = listener.GetContext();

            // Traitement de la requête GET sur la page "hello"
            if (context.Request.HttpMethod == "GET" && context.Request.Url.AbsolutePath == "/hello")
            {
                // Afficher le texte "Hello" comme réponse
                string response = "<html><body>Hello</body></html>";
                context.Response.ContentType = "text/html";
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response);
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                context.Response.OutputStream.Close();
            }
            else
            {
                // Réponse HTTP 404 (Not Found) pour les requêtes non gérées
                context.Response.StatusCode = 404;
                context.Response.StatusDescription = "Not Found";
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes("Not Found");
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                context.Response.OutputStream.Close();
            }
        }
    }
}
```
Ce code commence par créer un nouvel objet `HttpListener` et configurer l'écouteur pour répondre aux requêtes HTTP sur le port 8080. Ensuite, il lance l'écouteur en appelant la méthode `Start()`.

La boucle while attend les requêtes et traite celles qui sont envoyées sur la page "hello". Si la requête est un GET sur la page "hello", il affiche le texte "Hello" comme réponse en configurant le type de contenu de la réponse à "text/html" et en écrivant le texte comme un flux de données.

Si la requête ne correspond pas à la page "hello", il envoie une réponse HTTP 404 (Not Found) avec un message "Not Found".

Notez que cet exemple est très simple et ne gère pas les erreurs ni les connexions multiples. Vous devrez peut-être ajouter des mechaniques de sécurité, de gestion des erreurs et de connexion pour créer un serveur HTTP vraiment fonctionnel.<|start_header_id|>assistant<|end_header_id|>

