```
class PasswordGenerator {
  constructor(options = {}) {
    this.length = options.length || 12; // Longitud predeterminada de la contraseña
    this.useUppercase = options.useUppercase || true; // Usar mayúsculas (verdadero por defecto)
    this.useLowercase = options.useLowercase || true; // Usar minúsculas (verdadero por defecto)
    this.useNumbers = options.useNumbers || true; // Usar números (verdadero por defecto)
    this.useSpecialCharacters = options.useSpecialCharacters || false; // Usar caracteres especiales (falso por defecto)
  }

  generatePassword() {
    const characters = [];
    if (this.useUppercase) characters.push(...Array(4).fill('ABCDEFGHIJKLMNOPQRSTUVWXYZ'));
    if (this.useLowercase) characters.push(...Array(4).fill('abcdefghijklmnopqrstuvwxyz'));
    if (this.useNumbers) characters.push(...Array(2).fill('0123456789'));
    if (this.useSpecialCharacters) characters.push(...Array(2).fill('!@#$%^&*()-+'));

    const password = [];
    for (let i = 0; i < this.length; i++) {
      password.push(characters[Math.floor(Math.random() * characters.length)]);
    }
    return password.join('');
  }
}
```
