import org.pcap4j.packet.*;

public class Sniffer extends Pcap {
    public Sniffer(String device, int snapLen, int timeout) throws PcapNativeNotSupportedException, PcapNetworkInterfaceNotFoundException {
        super(PcapNative.parse device(device), snapLen, timeout);
        System.out.println("Capturing on device " + device);
    }

    public void run() {
        while (true) {
            Packet packet = receivePacket();
            if (packet != null) {
                PacketHeader header = packet.getHeader();
                String srcIP = header.getSource().get().getHostAddress();
                String dstIP = header.getDestination().get().getHostAddress();
                String data = packet.getDate().toString();
                System.out.println("Package received: " + srcIP + " -> " + dstIP + " (" + data + ")");
            }
        }
    }

    public static void main(String[] args) throws PcapNativeNotSupportedException, PcapNetworkInterfaceNotFoundException {
        Sniffer sniffer = new Sniffer("eth0", 65535, 1000);
        sniffer.run();
    }
}
```
