    for (i = 0; i < 7; i++) {
        if (board[i * 3] === board[i * 3 + 1] && board[i * 3] === board[i * 3 + 2] && board[i * 3] != "1" && board[i * 3] != "2") {
            return board[i * 3];
        }
    }
    for (i = 0; i < 3; i++) {
        if (board[i] === board[i + 3] && board[i] === board[i + 6] && board[i] != "1" && board[i] != "2") {
            return board[i];
        }
    }
    if (board[0] === board[4] && board[0] === board[8] && board[0] != "1" && board[0] != "2") {
        return board[0];
    }
    if (board[2] === board[4] && board[2] === board[6] && board[2] != "1" && board[2] != "2") {
        return board[2];
    }
    return null;
}

