            board[i] = "X";
            var score = minimax("O", false);
            board[i] = "1";
            if (score > bestScore) {
                bestScore = score;
                bestMove = i;
            }
        }
    }
    board[bestMove] = "X";
}

// Minimax algorithm
function minimax(player, isMaximizing) {
    var score = 0;
    var result = checkWin();
    if (result === "X") {
        return 1000;
    }
    if (result === "O") {
        return -1000;
    }
    if (checkDraw()) {
        return 0;
    }
    if (isMaximizing) {
        for (i = 0; i < 9; i++) {
            if (board[i] === "1" || board[i] === "2") {
                board[i] = player;
                var score = minimax("1", false);
                board[i] = "1";
                if (score > bestScore) {
                    bestScore = score;
                }
